{"implementation":"def solve(case):
    edges = case['edges']
    communities = case['communities']
    resolution = case['resolution']
    m = 0.0
    deg = {}
    internal = {}
    for u, v, w in edges:
        m += w
        deg[u] = deg.get(u, 0.0) + w
        deg[v] = deg.get(v, 0.0) + w
        if communities[u] == communities[v]:
            com = communities[u]
            internal[com] = internal.get(com, 0.0) + w
    community_deg_sum = {}
    for node, com in communities.items():
        community_deg_sum[com] = community_deg_sum.get(com, 0.0) + deg.get(node, 0.0)
    Q = 0.0
    for com in set(communities.values()):
        In = internal.get(com, 0.0)
        S = community_deg_sum.get(com, 0.0)
        Q += In - resolution * (S * S) / (2.0 * m)
    Q /= (2.0 * m)
    return Q"}
